#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAX_LEN 64

int main(int argc, char *argv[])
{
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }
    const char *pattern = argv[1];
    const char *text = argv[2];
    size_t pat_len = strlen(pattern);
    size_t txt_len = strlen(text);
    if (pat_len > MAX_LEN || txt_len > MAX_LEN) {
        puts("USAGE");
        return 0;
    }
    bool dp[MAX_LEN + 1][MAX_LEN + 1] = { false };
    dp[0][0] = true;
    for (size_t i = 1; i <= pat_len; ++i) {
        if (pattern[i - 1] == '*')
            dp[i][0] = dp[i - 1][0];
        else
            dp[i][0] = false;
    }
    for (size_t i = 1; i <= pat_len; ++i) {
        for (size_t j = 1; j <= txt_len; ++j) {
            char pc = pattern[i - 1];
            char tc = text[j - 1];
            if (pc == '*') {
                dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
            } else if (pc == '?' || pc == tc) {
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                dp[i][j] = false;
            }
        }
    }
    if (dp[pat_len][txt_len])
        puts("MATCH");
    else
        puts("NO_MATCH");
    return 0;
}
